mapper.select:
SELECT id, operate_emp_id, operate_ip, operate_time, class_name, method_name, request_method, request_url, method_params, return_value, result_status, error_msg, cost_time FROM operate_log
AND class_name LIKE CONCAT('%', #{param.className}, '%')
AND method_name LIKE CONCAT('%', #{param.methodName}, '%')
AND result_status = #{param.resultStatus}
AND operate_time BETWEEN #{param.begin} AND #{param.end}
ORDER BY operate_time DESC
